package com.arenashowdown.lobby;
import com.arenashowdown.api.*;import net.kyori.adventure.text.Component;import net.kyori.adventure.text.serializer.legacy.LegacyComponentSerializer;import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.block.*;import org.bukkit.event.entity.*;import org.bukkit.event.player.*;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.scheduler.BukkitTask;import org.jetbrains.annotations.NotNull;import java.util.*;
public final class ArenaLobbyPlugin extends JavaPlugin implements Listener,TabExecutor{
 private final LegacyComponentSerializer legacy=LegacyComponentSerializer.legacyAmpersand();private LobbyState state;private VisualManager visuals;private LobbyMenu menu;private LobbyItems items;private BukkitTask refreshTask;private boolean refreshWarning;
 @Override public void onLoad(){saveDefaultConfig();getConfig().options().copyDefaults(true);saveConfig();}
 @Override public void onEnable(){saveDefaultConfig();ArenaApi arena=getServer().getServicesManager().load(ArenaApi.class);OrchestrationApi orchestration=getServer().getServicesManager().load(OrchestrationApi.class);if(arena==null||orchestration==null||!loadExistingWorld()){getLogger().severe("ArenaCore ou mundo existente indisponivel; plugin desabilitado sem criar mapas.");getServer().getPluginManager().disablePlugin(this);return;}state=new LobbyState(arena,orchestration);visuals=new VisualManager(this);menu=new LobbyMenu(this);items=new LobbyItems(this);getServer().getPluginManager().registerEvents(this,this);getServer().getPluginManager().registerEvents(menu,this);getServer().getPluginManager().registerEvents(items,this);PluginCommand command=getCommand("lobby");command.setExecutor(this);command.setTabCompleter(this);checkAliasConflicts();Bukkit.getScheduler().runTask(this,visuals::rebuild);schedule();getLogger().info("ArenaLobby 4.1 habilitado sem alterar blocos.");}
 @Override public void onDisable(){if(refreshTask!=null)refreshTask.cancel();if(visuals!=null)visuals.shutdown();}
 private boolean loadExistingWorld(){String n=getConfig().getString("world","cassino_lobby_v2");if(Bukkit.getWorld(n)!=null)return true;java.io.File level=new java.io.File(new java.io.File(Bukkit.getWorldContainer(),n),"level.dat");return level.isFile()&&new WorldCreator(n).createWorld()!=null;}
 private void schedule(){if(refreshTask!=null)refreshTask.cancel();long period=Math.max(40,getConfig().getLong("refresh-seconds",5)*20);refreshTask=Bukkit.getScheduler().runTaskTimer(this,this::refresh,1,period);}
 void refresh(){state.refresh(championship(),Math.max(10,getConfig().getInt("scoreboard.entries",3))).whenComplete((v,e)->{if(!isEnabled())return;Bukkit.getScheduler().runTask(this,()->{if(e!=null){if(!refreshWarning)getLogger().warning("Dados do campeonato indisponiveis; repeticoes suprimidas: "+root(e).getMessage());refreshWarning=true;return;}refreshWarning=false;visuals.invalidate();visuals.update();});});}
 Component text(String value){return legacy.deserialize(value==null?"":value);}String legacy(String value){return value.replace('&','§');}LobbyState state(){return state;}LobbyMenu menu(){return menu;}String championship(){return getConfig().getString("championship","principal");}World world(){return Bukkit.getWorld(getConfig().getString("world","cassino_lobby_v2"));}boolean isLobby(World w){return w!=null&&w.equals(world());}boolean parkourAvailable(){var p=Bukkit.getPluginManager().getPlugin("ArenaParkour");return p!=null&&p.isEnabled()&&!getConfig().getString("minigames.parkour.arena","").isBlank();}
 Location location(String path){World w=Bukkit.getWorld(getConfig().getString(path+".world",getConfig().getString("world")));if(w==null||!getConfig().contains(path+".x"))return null;double x=getConfig().getDouble(path+".x"),y=getConfig().getDouble(path+".y"),z=getConfig().getDouble(path+".z");return Double.isFinite(x)&&Double.isFinite(y)&&Double.isFinite(z)?new Location(w,x,y,z,(float)getConfig().getDouble(path+".yaw"),(float)getConfig().getDouble(path+".pitch")):null;}
 private void saveLocation(String path,Location l){getConfig().set(path+".world",l.getWorld().getName());getConfig().set(path+".x",l.getX());getConfig().set(path+".y",l.getY());getConfig().set(path+".z",l.getZ());getConfig().set(path+".yaw",l.getYaw());getConfig().set(path+".pitch",l.getPitch());saveConfig();}
 void returnToLobby(Player p){if(state.view.active(p.getUniqueId())||p.getScoreboard().getObjective("parkour")!=null){p.sendMessage(text("&cVoce esta em uma partida ativa. Conclua ou abandone pelas regras do minigame."));return;}Location target=location("spawn");if(target==null){p.sendMessage(text("&cO spawn do lobby ainda nao foi configurado ou o mundo nao existe."));return;}if(!safe(target)){p.sendMessage(text("&cO spawn configurado nao esta seguro. Avise um administrador; ele nao foi substituido."));return;}p.teleportAsync(target).thenAccept(ok->{if(ok&&isEnabled())Bukkit.getScheduler().runTask(this,()->p.sendMessage(text(getConfig().getString("messages.returned","&7Voce retornou ao lobby."))));});}
 private boolean safe(Location l){if(l.getWorld()==null||!l.getWorld().getWorldBorder().isInside(l))return false;return l.getBlock().isPassable()&&l.clone().add(0,1,0).getBlock().isPassable()&&l.clone().add(0,-1,0).getBlock().getType().isSolid();}
 @EventHandler public void join(PlayerJoinEvent e){Player p=e.getPlayer();Bukkit.getScheduler().runTaskLater(this,()->{if(!p.isOnline())return;if(getConfig().getBoolean("return.auto-on-join",true)&&!state.view.active(p.getUniqueId())&&(isLobby(p.getWorld())||p.getWorld().equals(Bukkit.getWorlds().getFirst())))returnToLobby(p);if(isLobby(p.getWorld()))enter(p);},20);}
 @EventHandler public void changed(PlayerChangedWorldEvent e){Player p=e.getPlayer();if(isLobby(p.getWorld()))Bukkit.getScheduler().runTaskLater(this,()->enter(p),2);else if(isLobby(e.getFrom())){items.remove(p);visuals.leave(p);}}
 private void enter(Player p){items.give(p);visuals.updatePlayer(p);}
 @EventHandler public void interaction(PlayerInteractEntityEvent e){if(!isLobby(e.getPlayer().getWorld())||!e.getRightClicked().getScoreboardTags().contains("arena_lobby_interaction"))return;e.setCancelled(true);String a=e.getRightClicked().getScoreboardTags().stream().filter(x->x.startsWith("arena_lobby_action_")).findFirst().orElse("").substring("arena_lobby_action_".length());if(a.equals("menu"))menu.open(e.getPlayer());else e.getPlayer().performCommand("arena "+(a.equals("ranking")?"ranking ":"status ")+championship());}
 @EventHandler public void breaking(BlockBreakEvent e){if(protect(e.getPlayer()))e.setCancelled(true);}@EventHandler public void placing(BlockPlaceEvent e){if(protect(e.getPlayer()))e.setCancelled(true);}@EventHandler public void damage(EntityDamageEvent e){if(isLobby(e.getEntity().getWorld())&&getConfig().getBoolean("protection.damage",true))e.setCancelled(true);}@EventHandler public void explode(EntityExplodeEvent e){if(isLobby(e.getLocation().getWorld()))e.blockList().clear();}@EventHandler public void ignite(BlockIgniteEvent e){if(isLobby(e.getBlock().getWorld())&&getConfig().getBoolean("protection.fire",true))e.setCancelled(true);}private boolean protect(Player p){return isLobby(p.getWorld())&&getConfig().getBoolean("protection.blocks",true)&&!(p.hasPermission("arena.lobby.admin")&&p.getGameMode()==GameMode.CREATIVE);}
 @Override public boolean onCommand(@NotNull CommandSender s,@NotNull Command c,@NotNull String label,String @NotNull[]a){if(a.length==0){if(s instanceof Player p)returnToLobby(p);else help(s);return true;}try{switch(a[0].toLowerCase()){case"spawn"->returnToLobby(player(s));case"menu"->menu.open(player(s));case"setspawn"->{admin(s);Player p=player(s);if(!safe(p.getLocation()))throw new IllegalArgumentException("Sua posicao nao e segura (piso solido e dois blocos livres sao obrigatorios).");saveLocation("spawn",p.getLocation());s.sendMessage(text("&aSpawn salvo com mundo, coordenadas e orientacao."));}case"setchampionship"->{admin(s);need(a,2,"/lobby setchampionship <id>");getConfig().set("championship",a[1]);saveConfig();refresh();}case"hologram"->hologram(s,a);case"reload"->{admin(s);reloadConfig();schedule();visuals.rebuild();refresh();s.sendMessage(text("&aConfiguracao recarregada sem duplicar tarefas."));}case"status"->s.sendMessage(text("&6ArenaLobby: &fworld="+(world()!=null)+", campeonato="+championship()+", parkour="+parkourAvailable()));default->help(s);}}catch(Exception e){s.sendMessage(text("&c"+e.getMessage()));}return true;}
 private void hologram(CommandSender s,String[]a){admin(s);Player p=player(s);need(a,3,"/lobby hologram <create|move|remove> <id> [tipo]");String path="holograms."+a[2];if(a[1].equalsIgnoreCase("remove"))getConfig().set(path,null);else{if(a[1].equalsIgnoreCase("create")){need(a,4,"/lobby hologram create <id> <ranking|championship|last>");getConfig().set(path+".type",a[3]);}saveLocation(path,p.getLocation());}saveConfig();visuals.rebuild();s.sendMessage(text("&aHologramas atualizados."));}
 private void checkAliasConflicts(){for(String alias:List.of("l","hub")){Command command=Bukkit.getCommandMap().getCommand(alias);if(command!=null&&!command.getName().equalsIgnoreCase("lobby"))getLogger().warning("Alias /"+alias+" registrado por outro comando; use /lobby ou /arenalobby:"+alias);}}
 private void admin(CommandSender s){if(!s.hasPermission("arena.lobby.admin"))throw new IllegalArgumentException("Sem permissao: arena.lobby.admin");}private Player player(CommandSender s){if(!(s instanceof Player p))throw new IllegalArgumentException("Comando exclusivo para jogador.");return p;}private void need(String[]a,int n,String usage){if(a.length<n)throw new IllegalArgumentException("Uso: "+usage);}private void help(CommandSender s){s.sendMessage(text("&6/lobby, /l, /hub &7- retornar | &6/lobby menu &7- abrir menu"));}private Throwable root(Throwable e){while(e.getCause()!=null)e=e.getCause();return e;}
 @Override public List<String>onTabComplete(@NotNull CommandSender s,@NotNull Command c,@NotNull String l,String @NotNull[]a){if(a.length==1)return List.of("menu","spawn","setspawn","setchampionship","hologram","reload","status").stream().filter(x->x.startsWith(a[0].toLowerCase())).toList();if(a.length==2&&a[0].equalsIgnoreCase("hologram"))return List.of("create","move","remove");if(a.length==4&&a[0].equalsIgnoreCase("hologram"))return List.of("ranking","championship","last");return List.of();}
}
